<script setup lang="ts">import{Head,Link,useForm}from'@inertiajs/vue3';import PageHeader from '@/Components/Shared/PageHeader.vue';import{Button}from'@/components/ui/button';defineProps<{lead:any}>();const a=useForm({type:'note',subject:'',details:'',follow_up_at:''});</script><template><Head :title="lead.company_name"/><div class="space-y-6 p-6"><div class="flex justify-between"><PageHeader :title="lead.company_name" :description="`${lead.stage} · ${lead.probability}% probability`"/><div class="flex gap-2"><Link :href="`/admin/sponsorship-proposals/create?lead=${lead.id}`"><Button>Create Proposal</Button></Link><Link :href="`/admin/sponsorship-leads/${lead.id}/edit`"><Button variant="outline">Edit</Button></Link></div></div><div class="grid gap-6 lg:grid-cols-2"><section class="rounded-xl border p-5"><h2 class="font-semibold">Lead Details</h2><p class="mt-3">{{lead.contact_name}} · {{lead.contact_email}}</p><p class="text-muted-foreground">Owner: {{lead.owner?.name??'Unassigned'}}</p><p class="mt-4 whitespace-pre-wrap">{{lead.notes}}</p></section><form @submit.prevent="a.post(`/admin/sponsorship-leads/${lead.id}/activities`,{onSuccess:()=>a.reset()})" class="rounded-xl border p-5"><h2 class="font-semibold">Record Activity</h2><input v-model="a.subject" placeholder="Subject" class="mt-3 w-full rounded-md border p-2"/><textarea v-model="a.details" placeholder="Details" class="mt-3 w-full rounded-md border p-2"/><Button class="mt-3">Add Activity</Button></form></div><section class="rounded-xl border p-5"><h2 class="font-semibold">Activity History</h2><div v-for="x in lead.activities" :key="x.id" class="border-b py-3"><div class="font-medium">{{x.subject}}</div><div class="text-sm text-muted-foreground">{{x.type}} · {{x.user?.name}}</div><p>{{x.details}}</p></div></section></div></template>